+// API keys, roles and the audit log of data-changing requests.
+
+/** Finds the API key record for `key`, or null if unknown. */
+export function findApiKey(store, key) {
+  return (store.data.apiKeys ?? []).find((entry) => entry.key === key) ?? null;
+}
+
+/** Appends an audit entry for a data-changing request. */
+export function recordAudit(store, { time, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { time, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Lists audit entries, newest first. */
+export function listAudit(store) {
+  return (store.data.audit ?? []).slice().reverse();
+}
