+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: auth("viewer-key") })).status, 200);
+
+  const cookRes = await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("viewer-key"), body: { portions: 1 } });
