+  assert.equal(orderRes.body.error.code, "forbidden");
+
+  const auditRes = await handle({ path: "/audit", headers: auth("viewer-key") });
+  assert.equal(auditRes.status, 403);
+  assert.equal(auditRes.body.error.code, "forbidden");
+});
+
