+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", headers: auth("cook-key"), body: { allergens: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: auth("cook-key") })).status, 403);
